import{_ as o,c as t,o as d,b0 as a}from"./chunks/framework.CwEpjpYu.js";const m=JSON.parse('{"title":"LV112-自动侧边栏的限制与避坑","description":null,"frontmatter":{"title":"LV112-自动侧边栏的限制与避坑","date":"2026-09-20T19:48:48.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/plugin/standalone-plugin/126d5cf377202ef2c6c29be6","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-09-20T19:48:48.751Z","fulluuid":"2c6c29be61c445d38bfa1576f7a1547e","useduuid":"2c6c29be6"}},"headers":[],"relativePath":"sdoc/03-插件/01-独立插件包/LV112-自动侧边栏的限制与避坑.md","filePath":"sdoc/03-插件/01-独立插件包/LV112-自动侧边栏的限制与避坑.md","lastUpdated":1789909188000}'),r={name:"sdoc/03-插件/01-独立插件包/LV112-自动侧边栏的限制与避坑.md"};function c(i,e,n,s,l,h){return d(),t("div",null,e[0]||(e[0]=[a('<h1 id="lv112-自动侧边栏的限制与避坑" tabindex="-1">LV112-自动侧边栏的限制与避坑 <a class="header-anchor" href="#lv112-自动侧边栏的限制与避坑" aria-label="Permalink to &quot;LV112-自动侧边栏的限制与避坑&quot;">​</a></h1><p>本文是自动侧边栏系列最后一篇，汇总配置时&quot;不看源码不知道&quot;的限制：生成时机、忽略机制、命名约定匹配、排序规则，以及 README 与实际实现之间的偏差清单。前四篇见 <a href="./LV100-自动侧边栏总览.html">总览</a>、<a href="./LV103-自动侧边栏配置详解.html">配置详解</a>、<a href="./LV106-自动侧边栏之filePath模式.html">filePath 模式</a>、<a href="./LV109-自动侧边栏之rewrites模式.html">rewrites 模式</a>。</p><h2 id="一、生成时机限制" tabindex="-1">一、生成时机限制 <a class="header-anchor" href="#一、生成时机限制" aria-label="Permalink to &quot;一、生成时机限制&quot;">​</a></h2><h3 id="_1-启动时一次性生成" tabindex="-1">1. 启动时一次性生成 <a class="header-anchor" href="#_1-启动时一次性生成" aria-label="Permalink to &quot;1. 启动时一次性生成&quot;">​</a></h3><p>数据生成只发生在 Vite <code>config()</code> 钩子里，闭包变量 <code>isExecute</code> 保证 dev + build 全程只执行一次。因此<strong>运行期间的一切文件变动（新增、删除、改名、移动、改 frontmatter 标题）都不会反映到导航/侧边栏，必须重启 dev 服务或重新 build</strong>。改了文档标题侧边栏没变、新加的文档侧边栏没有，先重启再说。</p><h3 id="_2-restart-配置项无效" tabindex="-1">2. <code>restart</code> 配置项无效 <a class="header-anchor" href="#_2-restart-配置项无效" aria-label="Permalink to &quot;2. `restart` 配置项无效&quot;">​</a></h3><p><code>SidebarOption</code> 类型里声明了 <code>restart?: boolean</code>（&quot;md 创建或删除时是否重启服务&quot;），但 auto-nav-sidebar <strong>没有实现对应的 <code>configureServer</code> 监听</strong>——这个能力只在 sidebar-resolve 版插件里存在（watcher 监听 md 增删后调 <code>restart()</code>）。在 mist 主题下配置它没有任何效果。</p><h3 id="_3-路径不存在时的静默兜底" tabindex="-1">3. 路径不存在时的静默兜底 <a class="header-anchor" href="#_3-路径不存在时的静默兜底" aria-label="Permalink to &quot;3. 路径不存在时的静默兜底&quot;">​</a></h3><p>扫描目录不存在时，插件不会报错，而是注入一份<strong>内置的测试数据</strong>（<code>createTestSidebarData</code> 里写死的 Guide/Config 等英文示例）。看到侧边栏出现一堆无关的英文条目，第一反应应该是：<code>path</code> 配错了或目录被移动了。</p><h2 id="二、忽略机制" tabindex="-1">二、忽略机制 <a class="header-anchor" href="#二、忽略机制" aria-label="Permalink to &quot;二、忽略机制&quot;">​</a></h2><h3 id="_1-默认黑名单只增不减" tabindex="-1">1. 默认黑名单只增不减 <a class="header-anchor" href="#_1-默认黑名单只增不减" aria-label="Permalink to &quot;1. 默认黑名单只增不减&quot;">​</a></h3><p>侧边栏与导航栏都固定忽略 <code>[&quot;node_modules&quot;, &quot;dist&quot;, &quot;.vitepress&quot;, &quot;public&quot;]</code>，用户 <code>ignoreList</code> 是<strong>追加</strong>合并（<code>[...DEFAULT_IGNORE_DIR, ...ignoreList]</code>）。没有配置项能把默认目录从黑名单里捞出来——比如想在 public 旁放文档目录，只能换名字。</p><h3 id="_2-匹配的是名字不是路径" tabindex="-1">2. 匹配的是名字不是路径 <a class="header-anchor" href="#_2-匹配的是名字不是路径" aria-label="Permalink to &quot;2. 匹配的是名字不是路径&quot;">​</a></h3><p><code>ignoreList</code> 与黑名单都按<strong>条目名</strong>精确匹配（正则则 <code>test</code> 名字），不是路径匹配。<code>ignoreList: [&quot;test&quot;]</code> 会忽略<strong>每一层</strong>叫 test 的目录；想只忽略某一层的，用正则配合完整文件名，或用 <code>beforeCreateSidebarItems</code> 钩子按需过滤。</p><h3 id="_3-index-md-的三重开关" tabindex="-1">3. index.md 的三重开关 <a class="header-anchor" href="#_3-index-md-的三重开关" aria-label="Permalink to &quot;3. index.md 的三重开关&quot;">​</a></h3><p>（1）根目录 index.md：<code>scannerRootMd</code> 分支里永远排除；</p><p>（2）各目录 index.md：mist 默认 <code>ignoreList: [&quot;index.md&quot;, &quot;README.md&quot;]</code> 排除；不配置则目录页会以&quot;目录名&quot;为标题出现在侧边栏；</p><p>（3）<code>ignoreIndexMd: true</code>：再显式排除一层（含 <code>.MD</code> 大写扩展名）。</p><h2 id="三、命名约定匹配限制" tabindex="-1">三、命名约定匹配限制 <a class="header-anchor" href="#三、命名约定匹配限制" aria-label="Permalink to &quot;三、命名约定匹配限制&quot;">​</a></h2><p>这是对 mist 文档库影响最大的一节。插件的序号体系是为 <code>01.标题.md</code>（数字 + 点分隔）设计的，而 mist 库统一用 <code>LVxxx-标题.md</code> 和 <code>NN-中文目录</code>（连字符），两套约定并不匹配：</p><h3 id="_1-序号解析不认识连字符" tabindex="-1">1. 序号解析不认识连字符 <a class="header-anchor" href="#_1-序号解析不认识连字符" aria-label="Permalink to &quot;1. 序号解析不认识连字符&quot;">​</a></h3><p><code>resolveFileName</code> 只按点（或 <code>indexSeparator</code> 自定义分隔符）切序号。<code>LV001-pnpm工作区.md</code> 解析不出数字序号 → 进无序号队列、<code>sort</code> 值取缺省 9999；<code>01-开发</code> 目录名解析不出 <code>01</code> → 侧边栏目录文本原样带 <code>01-</code> 前缀（实测如此，本站侧边栏显示的就是 <code>01-独立插件包</code>）。</p><h3 id="_2-排序侥幸正确的原因" tabindex="-1">2. 排序侥幸正确的原因 <a class="header-anchor" href="#_2-排序侥幸正确的原因" aria-label="Permalink to &quot;2. 排序侥幸正确的原因&quot;">​</a></h3><p>无序号条目按 <code>readdirSync</code> 返回顺序进入稳定排序，readdirSync 在 Windows/Linux 上都近似字母序，而 <code>LV001 &lt; LV004 &lt; LV007</code> 的<strong>三位零填充字典序恰好等于数值序</strong>——这正是库规范强制 LVxxx 三位宽度的原因之一。一旦出现两位编号（LV99 与 LV100 混排）字典序就错乱。</p><h3 id="_3-想要正确行为的两条路" tabindex="-1">3. 想要正确行为的两条路 <a class="header-anchor" href="#_3-想要正确行为的两条路" aria-label="Permalink to &quot;3. 想要正确行为的两条路&quot;">​</a></h3><p>（1）<strong>用回点分隔命名</strong>（<code>01.标题.md</code>）：序号、标题剥离全部生效，但与库规范冲突，不推荐；</p><p>（2）<strong>frontmatter <code>sidebarSort</code></strong>：给关键文档手工设排序值，或开启 <code>sortNumFromFileName</code>（但连字符命名解析不出序号，对 mist 库无效）。目录标题想去掉 <code>01-</code> 前缀，可开 <code>titleFormMd: true</code> 让标题取自各目录 index.md 的 frontmatter title（tdoc 生成的目录页 title 恰好是去掉序号的目录名），代价是文章标题也会转而读 md 一级标题。</p><h3 id="_4-同名-md-抑制是隐藏行为" tabindex="-1">4. 同名 md 抑制是隐藏行为 <a class="header-anchor" href="#_4-同名-md-抑制是隐藏行为" aria-label="Permalink to &quot;4. 同名 md 抑制是隐藏行为&quot;">​</a></h3><p>目录旁边存在同名 md（<code>01-开发/</code> 与 <code>01-开发.md</code> 并存）时，目录节点被跳过。误创建同名文件会让整个目录从侧边栏消失，且只有一条不起眼的逻辑分支，排查时不容易想到。</p><h2 id="四、排序与序号规则" tabindex="-1">四、排序与序号规则 <a class="header-anchor" href="#四、排序与序号规则" aria-label="Permalink to &quot;四、排序与序号规则&quot;">​</a></h2><p>（1）<strong>同序号覆盖</strong>：同一层两个文件解析出相同序号（点分隔命名下），后处理的覆盖先处理的，仅有一条警告；</p><p>（2）<strong>fileIndexPrefix 默认关闭</strong>：类型与 README 里&quot;默认 true&quot;不一致（见第六节），序号非法只有警告不拦截；</p><p>（3）<strong>sort 的性能账</strong>：<code>sort: true</code> 时每个 md 都要 <code>readFileSync</code> + gray-matter 解析。文档量大（几百篇）时启动耗时增加明显，纯靠文件名字典序排序的库可以关掉它换启动速度；</p><p>（4）<strong>无序号垫底</strong>：解析不出序号的条目永远排在有序号条目之后（<code>sidebarItemsNoIndex</code> 拼接在尾部）。</p><h2 id="五、结构与功能限制" tabindex="-1">五、结构与功能限制 <a class="header-anchor" href="#五、结构与功能限制" aria-label="Permalink to &quot;五、结构与功能限制&quot;">​</a></h2><h3 id="_1-多语言未实现" tabindex="-1">1. 多语言未实现 <a class="header-anchor" href="#_1-多语言未实现" aria-label="Permalink to &quot;1. 多语言未实现&quot;">​</a></h3><p><code>SidebarOption.localeRootDir</code>、locales 相关的类型定义继承自 sidebar-resolve，但 auto-nav-sidebar 的 config 钩子里<strong>没有任何 locales 分支</strong>——配置了国际化的站点，各语言的侧边栏会拿到同一份数据。需要多语言侧边栏时只能用 sidebar-resolve 版插件。</p><h3 id="_2-侧边栏-key-依赖一级目录的同前缀" tabindex="-1">2. 侧边栏 key 依赖一级目录的同前缀 <a class="header-anchor" href="#_2-侧边栏-key-依赖一级目录的同前缀" aria-label="Permalink to &quot;2. 侧边栏 key 依赖一级目录的同前缀&quot;">​</a></h3><p>rewrites 模式下侧边栏 key 取重写值的第二段，<strong>默认同一目录下所有文件的重写前缀一致</strong>（<code>sdoc/plugin/...</code>）。某目录下混入不同前缀的重写规则时，key 互相覆盖，部分侧边栏丢失。sidebar-resolve 提供的 <code>checkRewritesPrefix</code> 校验在 auto-nav-sidebar 里没有接线（类型里有、代码不读）。</p><h3 id="_3-中文-url-与部署环境" tabindex="-1">3. 中文 URL 与部署环境 <a class="header-anchor" href="#_3-中文-url-与部署环境" aria-label="Permalink to &quot;3. 中文 URL 与部署环境&quot;">​</a></h3><p>filePath 模式的链接带中文与空格，部署到部分静态托管（Nginx 未配编码、对象存储等）时可能 404。VitePress 内部会 <code>encodeURI</code>，一般场景可用，但对外分享链接不友好——这是切到 rewrites 模式（permalink 全英文）的主要动机之一。</p><h3 id="_4-注入只认对象或数组" tabindex="-1">4. 注入只认对象或数组 <a class="header-anchor" href="#_4-注入只认对象或数组" aria-label="Permalink to &quot;4. 注入只认对象或数组&quot;">​</a></h3><p><code>type: &quot;object&quot;</code> 时手写 sidebar 必须也是对象，<code>type: &quot;array&quot;</code> 时必须是数组，类型不符时手写部分被丢弃（只有一条告警）。混合场景先确认手写数据的形态。</p><h2 id="六、readme-与实现的差异清单" tabindex="-1">六、README 与实现的差异清单 <a class="header-anchor" href="#六、readme-与实现的差异清单" aria-label="Permalink to &quot;六、README 与实现的差异清单&quot;">​</a></h2><p>文档（README / 类型注释）与代码行为有出入的地方，配置时以本清单为准：</p><table tabindex="0"><thead><tr><th>条目</th><th>文档说法</th><th>实际行为</th></tr></thead><tbody><tr><td><code>fileIndexPrefix</code> 默认值</td><td>README 表格写 <code>true</code></td><td>代码默认 <code>false</code>（序号非法仅警告）</td></tr><tr><td><code>collapsed</code> 默认值</td><td>README 表格写 <code>true</code></td><td>代码默认 <code>undefined</code>（不折叠）</td></tr><tr><td><code>resolveRule</code></td><td>类型里有、Teek README 详述</td><td>auto-nav-sidebar <strong>不读此配置</strong>，模式由 <code>__create__</code> 标记自动判定</td></tr><tr><td><code>restart</code></td><td>类型注释&quot;md 增删时重启&quot;</td><td>未实现（仅 sidebar-resolve 有）</td></tr><tr><td><code>checkRewritesPrefix</code></td><td>类型里有</td><td>未接线，配置无效</td></tr><tr><td><code>localeRootDir</code> / locales</td><td>类型里有</td><td>未实现，多语言不生效</td></tr><tr><td>nav-sidebar 的 <code>getNavData(config, docsRoot)</code></td><td>README 示例带第二个路径参数</td><td>函数签名只收一个参数，第二个被忽略；根目录实际取 <code>process.cwd() + rootDir</code></td></tr><tr><td>nav-sidebar 的序号剥离</td><td>README 提到带序号文件排序</td><td>仅识别 <code>^[0-9]{2}-</code> 两位数字 + 连字符，三位 <code>LV001-</code> 不剥离</td></tr></tbody></table><p>【<strong>注意</strong>】</p><p>排查侧边栏问题的通用顺序：先 <code>debugInfo: true</code> 确认模式判定 → 再 <code>saveToFile: true</code> 拿到完整生成数据对照预期 → 最后对照本清单检查是不是踩了命名或时机限制。</p>',48)]))}const p=o(r,[["render",c]]);export{m as __pageData,p as default};
